static TreeNode* parseTree(const string& line) {
    size_t firstBracket = line.find('[', 1);
    size_t lastBracket = line.rfind(']');
    string inner = line.substr(firstBracket + 1, lastBracket - firstBracket - 1);

    if (inner.empty()) return nullptr;

    vector<string> parts;
    string token;
    stringstream ss(inner);
    while (getline(ss, token, ',')) {
        size_t start = token.find_first_not_of(" \t\r\n");
        size_t end = token.find_last_not_of(" \t\r\n");
        if (start == string::npos) parts.push_back("");
        else parts.push_back(token.substr(start, end - start + 1));
    }

    if (parts.empty() || parts[0] == "null") return nullptr;

    TreeNode* root = new TreeNode(stoi(parts[0]));
    queue<TreeNode*> q;
    q.push(root);

    size_t i = 1;
    while (!q.empty() && i < parts.size()) {
        TreeNode* node = q.front();
        q.pop();

        if (i < parts.size()) {
            const string& left = parts[i++];
            if (left != "null") {
                node->left = new TreeNode(stoi(left));
                q.push(node->left);
            }
        }

        if (i < parts.size()) {
            const string& right = parts[i++];
            if (right != "null") {
                node->right = new TreeNode(stoi(right));
                q.push(node->right);
            }
        }
    }

    return root;
}

