typedef struct TreeNode {
    int val;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

static void trim(char* s) {
    char* start = s;
    while (*start && isspace((unsigned char)*start)) start++;

    char* end = start + strlen(start);
    while (end > start && isspace((unsigned char)end[-1])) end--;
    *end = '\0';

    if (start != s) memmove(s, start, (size_t)(end - start + 1));
}

static TreeNode* newNode(int value) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->val = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static TreeNode* parseTree(const char* line) {
    const char* first = strchr(line, '[');
    if (first == NULL) return NULL;
    first = strchr(first + 1, '[');
    const char* last = strrchr(line, ']');
    if (first == NULL || last == NULL || last <= first) return NULL;

    size_t innerLen = (size_t)(last - first - 1);
    char* inner = (char*)malloc(innerLen + 1);
    memcpy(inner, first + 1, innerLen);
    inner[innerLen] = '\0';

    char* token = strtok(inner, ",");
    if (token == NULL) {
        free(inner);
        return NULL;
    }

    trim(token);
    if (strcmp(token, "null") == 0) {
        free(inner);
        return NULL;
    }

    TreeNode* root = newNode(atoi(token));
    TreeNode** queue = (TreeNode**)malloc(10000 * sizeof(TreeNode*));
    int head = 0, tail = 0;
    queue[tail++] = root;

    while (head < tail) {
        TreeNode* node = queue[head++];

        token = strtok(NULL, ",");
        if (token == NULL) break;
        trim(token);
        if (strcmp(token, "null") != 0) {
            node->left = newNode(atoi(token));
            queue[tail++] = node->left;
        }

        token = strtok(NULL, ",");
        if (token == NULL) break;
        trim(token);
        if (strcmp(token, "null") != 0) {
            node->right = newNode(atoi(token));
            queue[tail++] = node->right;
        }
    }

    free(queue);
    free(inner);
    return root;
}

int deepestLeavesSum(TreeNode* root) {
    TreeNode* queue[10000];
    int head = 0, tail = 0;
    int answer = 0;

    queue[tail++] = root;

    while (head < tail) {
        int levelEnd = tail;
        int levelSum = 0;

        while (head < levelEnd) {
            TreeNode* node = queue[head++];
            levelSum += node->val;
            if (node->left) queue[tail++] = node->left;
            if (node->right) queue[tail++] = node->right;
        }

        answer = levelSum;
    }

    return answer;
}

static void freeTree(TreeNode* root) {
    if (!root) return;
    TreeNode* queue[10000];
    int head = 0, tail = 0;
    queue[tail++] = root;
    while (head < tail) {
        TreeNode* node = queue[head++];
        if (node->left) queue[tail++] = node->left;
        if (node->right) queue[tail++] = node->right;
        free(node);
    }
}

